//! 速成 (Simplex / Quick) lookup, paging, and the Ctrl+Alt+, symbol keyboard.
//!
//! The merged codebook is generated by `build.rs` from the vendored
//! OpenVanilla `simplex-ext.cin` and the Digital Policy Office HKSCS-2016
//! JSON. See `data/SOURCES.md`.

use std::sync::OnceLock;

/// Maximum number of radical codes in 速成 (first + last only).
pub const MAX_CODES: usize = 2;

/// Candidates shown per page in the top bar.
pub const PAGE_SIZE: usize = 9;

