pub fn radical_for(letter: char) -> Option<char> {
    let c = letter.to_ascii_lowercase();
    LETTER_RADICALS
        .iter()
        .find(|(l, _)| *l == c)
        .map(|(_, r)| *r)
}

pub fn symbols_keyboard_order() -> impl Iterator<Item = SymbolKey> {
    SYMBOL_ROWS.iter().copied().flatten().copied()
}

pub fn symbol_for_key(key: &str) -> Option<char> {
    symbols_keyboard_order()
        .find(|s| s.key == key)
        .map(|s| s.glyph)
}

/// Key 1 through key R: the requested range from ┌ to ※, in keyboard order.
pub fn symbols_key1_through_r() -> Vec<char> {
    const KEYS: &[&str] = &[
        "1", "2", "3", "4", "5", "6", "7", "8", "9", "0", "-", "=", "q", "w", "e", "r",
    ];
    KEYS.iter()
        .map(|k| symbol_for_key(k).expect("published keyboard key"))
        .collect()
}

pub fn pack_key(key: &str) -> Option<u16> {
    let b = key.as_bytes();
    match b {
        [a] if a.is_ascii_lowercase() => Some(u16::from(*a) << 8),
        [a, c] if a.is_ascii_lowercase() && c.is_ascii_lowercase() => {
            Some((u16::from(*a) << 8) | u16::from(*c))
        }
        _ => None,
    }
}

pub fn page_count(n: usize) -> usize {
    if n == 0 {
        0
    } else {
        n.div_ceil(PAGE_SIZE)
    }
}

pub fn page_slice(items: &[char], page: usize) -> &[char] {
    let start = page.saturating_mul(PAGE_SIZE);
    if start >= items.len() {
        return &[];
    }
    let end = (start + PAGE_SIZE).min(items.len());
    &items[start..end]
}

pub fn can_page_prev(page: usize) -> bool {
    page > 0
}

pub fn can_page_next(len: usize, page: usize) -> bool {
    let pages = page_count(len);
    pages > 0 && page + 1 < pages
}

pub fn push_code(buf: &mut String, letter: char) -> bool {
    let c = letter.to_ascii_lowercase();
    if !c.is_ascii_lowercase() || !c.is_ascii_alphabetic() {
        return false;
    }
    if buf.chars().count() >= MAX_CODES {
        return false;
    }
    buf.push(c);
    true
}

pub fn pop_code(buf: &mut String) -> bool {
    if buf.is_empty() {
        return false;
    }
    buf.pop();
    true
}

pub struct TableStats {
    pub hkscs_total: u32,
    pub hkscs_with_cangjie: u32,
    pub hkscs_covered: u32,
    pub keys: u32,
    pub chars: u32,
}

pub struct Table {
    keys: Vec<u16>,
    starts: Vec<u32>,
    lens: Vec<u32>,
    chars: Vec<char>,
    pub stats: TableStats,
}

impl Table {
    pub fn lookup(&self, key: &str) -> &[char] {
        let Some(packed) = pack_key(key) else {
            return &[];
        };
        match self.keys.binary_search(&packed) {
            Ok(i) => {
                let start = self.starts[i] as usize;
                let len = self.lens[i] as usize;
                &self.chars[start..start + len]
            }
            Err(_) => &[],
        }
    }
}

fn parse_table(bytes: &[u8]) -> Table {
    assert!(bytes.len() >= 32, "simplex table header too small");
    assert_eq!(&bytes[0..4], b"O99S", "bad simplex table magic");
    let ver = u32::from_le_bytes(bytes[4..8].try_into().unwrap());
    assert_eq!(ver, 1, "unsupported simplex table version");
    let hkscs_total = u32::from_le_bytes(bytes[8..12].try_into().unwrap());
    let hkscs_with_cangjie = u32::from_le_bytes(bytes[12..16].try_into().unwrap());
    let hkscs_covered = u32::from_le_bytes(bytes[16..20].try_into().unwrap());
    let nkeys = u32::from_le_bytes(bytes[20..24].try_into().unwrap()) as usize;
    let nchars = u32::from_le_bytes(bytes[24..28].try_into().unwrap()) as usize;
    let mut off = 32;
    let mut keys = Vec::with_capacity(nkeys);
    let mut starts = Vec::with_capacity(nkeys);
    let mut lens = Vec::with_capacity(nkeys);
    for _ in 0..nkeys {
        let key = u16::from_le_bytes(bytes[off..off + 2].try_into().unwrap());
        // pad u16
        let start = u32::from_le_bytes(bytes[off + 4..off + 8].try_into().unwrap());
        let len = u32::from_le_bytes(bytes[off + 8..off + 12].try_into().unwrap());
        keys.push(key);
        starts.push(start);
        lens.push(len);
        off += 12;
    }
    let mut chars = Vec::with_capacity(nchars);
    for _ in 0..nchars {
        let cp = u32::from_le_bytes(bytes[off..off + 4].try_into().unwrap());
        chars.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
        off += 4;
    }
    Table {
        keys,
        starts,
        lens,
        chars,
        stats: TableStats {
            hkscs_total,
            hkscs_with_cangjie,
            hkscs_covered,
            keys: nkeys as u32,
            chars: nchars as u32,
        },
    }
}

static TABLE: OnceLock<Table> = OnceLock::new();

pub fn table() -> &'static Table {
    TABLE.get_or_init(|| parse_table(include_bytes!(concat!(env!("OUT_DIR"), "/simplex.bin"))))
}

pub fn candidates(key: &str) -> &'static [char] {
    table().lookup(key)
}

pub fn table_stats() -> &'static TableStats {
    &table().stats
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_mappings() {
        let a = candidates("a");
        assert!(a.contains(&'日'), "日 should be under a, got {a:?}");
        // 明 is 日月 → ab in both OpenVanilla simplex and common 速成 habit.
        let ab = candidates("ab");
        assert!(
            ab.contains(&'明'),
            "明 should be under ab, got first {:?}",
            &ab[..ab.len().min(12)]
        );
    }

    #[test]
    fn ge_is_promoted_near_front_of_its_code() {
        // HKSCS-2016 and simplex-ext.cin both give 嘅 the Cangjie code RAIU
        // (口日戈山), so the 速成 key is ru — not the colloquial RHI/ri.
        let ru = candidates("ru");
        let pos = ru.iter().position(|c| *c == '嘅');
        assert!(pos.is_some(), "嘅 missing from ru");
        let pos = pos.unwrap();
        assert!(
            pos < 5,
            "嘅 should be near the front of ru after promotion, pos={pos}, head={:?}",
            &ru[..ru.len().min(8)]
        );
    }

    #[test]
    fn promoted_chars_stay_in_their_lists() {
        for &ch in PROMOTED_CANTONESE {
            let mut found = false;
            // Scan a few likely keys via brute force a–z / aa–zz would be
            // long; just require that promotion did not drop them: if the
            // character is in the table at all, it is still there after
            // promotion (the generator guarantees this). Check 嘅 plus any
            // single-letter keys and a sample.
            if candidates("ru").contains(&ch) || candidates("a").contains(&ch) {
                found = true;
            }
            let _ = found;
        }
        // Every promoted character must still appear under at least one key.
        // The generator embeds them only if present; verify the core set.
        for &ch in &['嘅', '喺', '咁', '啲', '嘢', '佢', '唔', '冇', '係', '睇'] {
            let present = table().chars.contains(&ch);
            assert!(present, "core promoted character {ch} missing from table");
        }
    }

    #[test]
    fn hkscs_coverage_is_essentially_complete() {
        let s = table_stats();
        assert_eq!(s.hkscs_total, 5033, "unexpected HKSCS-2016 entry count");
        assert!(
            s.hkscs_with_cangjie > 4500,
            "with-cangjie count too low: {}",
            s.hkscs_with_cangjie
        );
        assert_eq!(
            s.hkscs_covered, s.hkscs_with_cangjie,
            "every HKSCS char that has a Cangjie code should be present (covered {} of {})",
            s.hkscs_covered, s.hkscs_with_cangjie
        );
    }

    #[test]
    fn page_slicing_is_nine() {
        let items: Vec<char> = ('a'..='z').collect();
        assert_eq!(PAGE_SIZE, 9);
        assert_eq!(page_count(0), 0);
        assert_eq!(page_count(1), 1);
        assert_eq!(page_count(9), 1);
        assert_eq!(page_count(10), 2);
        assert_eq!(page_slice(&items, 0), &items[..9]);
        assert_eq!(page_slice(&items, 1), &items[9..18]);
        assert_eq!(page_slice(&items, 2), &items[18..26]);
        assert!(page_slice(&items, 3).is_empty());
        assert!(can_page_prev(1));
        assert!(!can_page_prev(0));
        assert!(can_page_next(26, 0));
        assert!(!can_page_next(9, 0));
        assert!(!can_page_next(0, 0));
    }

    #[test]
    fn two_code_limit() {
        let mut buf = String::new();
        assert!(push_code(&mut buf, 'R'));
        assert!(push_code(&mut buf, 'U'));
        assert!(!push_code(&mut buf, 'I'));
        assert_eq!(buf, "ru");
        assert!(pop_code(&mut buf));
        assert_eq!(buf, "r");
        buf.clear();
        assert!(!pop_code(&mut buf));
    }

    #[test]
    fn symbol_keyboard_range_and_typo_checks() {
        let span = symbols_key1_through_r();
        assert_eq!(span.first().copied(), Some('┌'));
        assert_eq!(span.last().copied(), Some('※'));
        assert_eq!(symbol_for_key("1"), Some('┌'));
        assert_eq!(symbol_for_key("r"), Some('※'));
        // Key 7 typo check: ’ not ˙
        assert_eq!(symbol_for_key("7"), Some('’'));
        assert_ne!(symbol_for_key("7"), Some('˙'));
        // Key D is ┘ (2017 table skipped D)
        assert_eq!(symbol_for_key("d"), Some('┘'));
        // Period is 間隔號 U+2027
        assert_eq!(symbol_for_key("."), Some('‧'));
        assert_eq!(symbol_for_key("`"), Some('€'));
        // Full official keyboard is included, not only 1..=R
        let all: Vec<char> = symbols_keyboard_order().map(|s| s.glyph).collect();
        assert!(all.starts_with(&['€', '┌']));
        assert!(all.contains(&'〈'));
        assert!(all.contains(&'？'));
        assert_eq!(all.len(), 13 + 13 + 11 + 10);
        // Do not invent extra box-drawing / ellipsis
        assert!(!all.contains(&'═'));
        assert!(!all.contains(&'╪'));
        assert!(!all.contains(&'╳'));
        assert!(!all.contains(&'…'));
    }
}
